# Build a standalone solver using the three distinct base patterns.
def dihedrals(a):
    ans=[]
    for k in range(4):
        r=np.rot90(a,k)
        for x in (r,np.fliplr(r)):
            if not any(np.array_equal(x,y) for y in ans): ans.append(x)
    return ans

def solve(g):
    a=np.array(g)
    colors=sorted(set(a.ravel()))
    bases=[b,b2,b3]
    for base in bases:
        for cand in dihedrals(base):
            tiled=np.tile(cand,(2,2))
            for fg in colors:
                bg=colors[1] if fg==colors[0] else colors[0]
                binary=(a==fg)
                for i in range(20):
                    for j in range(20):
                        if np.array_equal(tiled[i:i+a.shape[0],j:j+a.shape[1]],binary):
                            return np.where(cand,fg,bg).tolist()
    raise ValueError('no matching template')

